#!/usr/bin/env python3
"""Redact an accidentally-posted string from the OpenCode SQLite DB.

The string is read from the DB itself (the user message identified by MSG_ID),
so it never appears in argv, environment, or this script's source.
Prints only counts, never content.
"""
import os
import sqlite3
import sys

DB = os.path.expanduser("~/.local/share/opencode/opencode.db")
MSG_ID = "msg_1ddbbe35c001rqwtAxB6F3XHyJ"
PLACEHOLDER = "[redacted]"
EXTRA_FILES = [
    os.path.expanduser(
        "~/.local/share/opencode/shell/5dadc7690882ac4807b80c8848691751d770e91e/"
        "sh_1ddbc1e14001BvqAYJBn2bt1aZ.out"
    ),
    os.path.expanduser("~/.local/share/opencode/log/opencode.log"),
]


def main() -> int:
    con = sqlite3.connect(DB, timeout=15)
    con.execute("PRAGMA busy_timeout=15000")
    con.execute("PRAGMA secure_delete=ON")

    row = con.execute(
        "SELECT json_extract(data,'$.text') FROM session_message WHERE id=?",
        (MSG_ID,),
    ).fetchone()
    if not row or not row[0]:
        print("needle unavailable (already redacted?) -- nothing to do")
        return 0
    needle = row[0]
    print(f"needle length: {len(needle)}")

    tables = [
        r[0]
        for r in con.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        )
    ]

    total = 0
    for table in tables:
        cols = [
            c[1]
            for c in con.execute(f'PRAGMA table_info("{table}")').fetchall()
        ]
        for col in cols:
            try:
                n = con.execute(
                    f'SELECT COUNT(*) FROM "{table}" WHERE instr("{col}", ?) > 0',
                    (needle,),
                ).fetchone()[0]
            except sqlite3.Error:
                continue
            if not n:
                continue
            con.execute(
                f'UPDATE "{table}" SET "{col}" = replace("{col}", ?, ?) '
                f'WHERE instr("{col}", ?) > 0',
                (needle, PLACEHOLDER, needle),
            )
            print(f"redacted {table}.{col}: {n} row(s)")
            total += n

    con.commit()
    print(f"db rows redacted: {total}")

    for pragma in ("wal_checkpoint(TRUNCATE)", "VACUUM", "wal_checkpoint(TRUNCATE)"):
        try:
            con.execute(f"PRAGMA {pragma}")
            print(f"ok: PRAGMA {pragma}")
        except sqlite3.Error as exc:
            print(f"warn: PRAGMA {pragma} -> {exc}")
