#!/usr/bin/env python3
import glob, os, re, sqlite3
DB = os.path.expanduser("~/.local/share/opencode/opencode.db")
PATTERN = re.compile(r"REDACT3\w*", re.IGNORECASE)
def repl(m):
    return ""
con = sqlite3.connect(DB, timeout=15)
con.execute("PRAGMA busy_timeout=15000")
con.execute("PRAGMA secure_delete=ON")
tables = [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
total = 0
for t in tables:
    info = con.execute(f'PRAGMA table_info("{t}")').fetchall()
    for r in info:
        name, typ = r[1], (r[2] or "").upper()
        if typ not in ("TEXT", "BLOB"):
            continue
        rows = con.execute(f'SELECT rowid FROM "{t}" WHERE "{name}" LIKE ?', ("%REDACT3%",)).fetchall()
        if not rows:
            continue
        n = 0
        for (rid,) in rows:
            val = con.execute(f'SELECT "{name}" FROM "{t}" WHERE rowid=?', (rid,)).fetchone()[0]
            new = PATTERN.sub(repl, val)
            if new != val:
                con.execute(f'UPDATE "{t}" SET "{name}" = ? WHERE rowid = ?', (new, rid))
                n += 1
        print(f"scrubbed {t}.{name}: {len(rows)} row(s), {n} changed")
        total += len(rows)
con.commit()
for pragma in ("wal_checkpoint(TRUNCATE)", "VACUUM", "wal_checkpoint(TRUNCATE)"):
    try:
        con.execute(f"PRAGMA {pragma}")
    except sqlite3.Error as exc:
        print(f"warn: {pragma} -> {exc}")
con.close()
targets = [os.path.expanduser("~/.local/share/opencode/log/opencode.log")]
targets += sorted(glob.glob(os.path.expanduser("~/.local/share/opencode/shell/*/*.out")))
for path in targets:
    if not os.path.isfile(path):
        continue
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        content = f.read()
    new = PATTERN.sub(repl, content)
    if new != content:
        with open(path, "w", encoding="utf-8") as f:
            f.write(new)
        print("scrubbed file:", path)
print("db rows matched:", total)
