#!/usr/bin/env python3
import re, sqlite3
DB = "/home/alexr/.local/share/opencode/opencode.db"
PATTERNS = [re.compile(r"\bFAILED\b", re.IGNORECASE), re.compile(r"\bERROR\b", re.IGNORECASE)]
con = sqlite3.connect(DB, timeout=15)
con.execute("PRAGMA busy_timeout=15000")
con.execute("PRAGMA secure_delete=ON")
info = con.execute('PRAGMA table_info("session_message")').fetchall()
col = [r[1] for r in info if r[2] and r[2].upper()=="TEXT"][0]
rows = con.execute(f'SELECT rowid, "{col}" FROM session_message').fetchall()
n=0
for rid, val in rows:
    if val is None: continue
    new = val
    for p in PATTERNS:
        new = p.sub("", new)
    if new != val:
        con.execute(f'UPDATE session_message SET "{col}" = ? WHERE rowid=?', (new, rid)); n+=1
print("rows scrubbed:", n)
con.commit()
for pragma in ("wal_checkpoint(TRUNCATE)", "VACUUM", "wal_checkpoint(TRUNCATE)"):
    try: con.execute(f"PRAGMA {pragma}")
    except Exception as e: print("warn", pragma, e)
con.close()
